L000964	\subsection{B.1 Spectral three-point correlation function}
L000965	In contrast to the codimension-one case, the generating function $\langle e^{-\alpha_+ \mC_+ -\alpha_- \mC_-} \rangle$ involves the spectral three-point correlators. We begin by reviewing relevant aspects of random matrix theory and deriving the universal form of the three-point function $\langle D(E_1)D(E_2)D(E_3)\rangle$, or equivalently $\langle \rho(E_1)\rho(E_2)\rho(E_3)\rangle$. For a comprehensive review on this topic, see \cite{Eynard:2015aea}.
L000966	
L000967	
L000968	Let $\mathcal{Z}_N$ denote the partition function of the $N \times N$ random matrix model:
L000969	\begin{equation}
L000970	\mathcal{Z}_N=\int \left(\prod_{i=1}^{N}d{E_i}\, e^{-V\left(E_i\right)}\right) \Delta\left(E_1, \cdots, E_{N}\right)^\beta
L000971	\end{equation}
L000972	where $\Delta(E_1, \cdots, E_N)$ is the Vandermonde determinant. The joint probability distribution of eigenvalues of random matrices is given by
L000973	\begin{equation}\label{eq:matrixR}
L000974	    R_n\left(E_1, \cdots E_{n}\right)=\frac{1}{\mathcal{Z}_N} \frac{N!}{(N-n)!}\prod_{i=1}^{n}e^{-V(E_i)}\int \left(\prod_{i=n+1}^{N}d{E_i}\, e^{-V\left(E_i\right)}\right) \Delta\left(E_1, \cdots E_{N}\right)^\beta\,.
L000975	\end{equation}
L000976	In terms of the Christoffel–Darboux (CD) kernel $K(E_i, E_j)$, the $n$-point joint eigenvalue distribution functions simplify to
L000977	\begin{equation}
L000978	R_n\left(E_1, \cdots E_{k}\right)=\det_{i, j=1, \cdots n} K\left(E_i, E_j\right) \,,
L000979	\end{equation}
L000980	with the diagonal part of the kernel defining the eigenvalue density, namely
L000981	\begin{equation}
L000982	     R_1 (K_i)  = K\left(E_i,E_i\right)  = \rho (E_i)  \,.
L000983	\end{equation}
L000984	The first two joint eigenvalue distributions read
L000985	\begin{equation}
L000986	    \begin{split}
L000987	    R_2 (K_i, K_j)  &=  K\left(E_i, E_i\right) K\left(E_j, E_j\right) - K\left(E_i, E_j\right)K\left(E_j, E_i\right) = \rho_i \rho_j - (K_{ij})^2 \,,
L000988	    \end{split}
L000989	\end{equation}
L000990	and
L000991	\begin{equation}
L000992	\begin{split}
L000993	R_3\left(E_i, E_j, E_k\right) &=\operatorname{det}\left(\begin{array}{lll}
L000994	K\left(E_i, E_i\right) & K\left(E_i, E_j\right) & K\left(E_i, E_k\right) \\
L000995	K\left(E_j, E_i\right) & K\left(E_j, E_j\right) & K\left(E_j, E_k\right) \\
L000996	K\left(E_k, E_i\right) & K\left(E_k, E_j\right) & K\left(E_k, E_k\right)
L000997	\end{array}\right) \\
L000998	&= \rho_i \rho_j \rho_k + 2 K_{ij}K_{jk}K_{ik} - \rho_i (K_{jk})^2 -\rho_j (K_{ik})^2  -\rho_k (K_{ij})^2 \,,
L000999	\end{split}
L001000	\end{equation}
L001001	To simplify some expressions, we have used the abbreviations:
L001002	\begin{equation}
L001003	K_{ij}= K(E_i, E_j) \,, \qquad \rho_i =K_{ii}= \rho(E_i)\,, \qquad \delta_{i,j}= \delta(E_i -E_j) \,.
L001004	\end{equation}
L001005	Joint eigenvalue distributions or spectral correlation functions play a central role in diagnosing quantum chaos, as they encode statistical information about the eigenvalue spectrum. In particular, one hallmark of chaotic quantum systems is the phenomenon of level repulsion:
L001006	\begin{equation}
L001007	    \boxed{\textbf{Level repulsion: }
L001008	    \text{the probability of two nearby levels being arbitrarily close is suppressed.}}
L001009	\end{equation}
L001010	This manifests in the vanishing of $n$-point spectral correlators when two arguments coincide:
L001011	\begin{equation}
L001012	  \boxed{  R_n (E_1, \cdots E_i,\cdots E_i, \cdots E_n) =0  \,. }
L001013	\end{equation}
L001014	To characterize spectral correlations more precisely, one typically studies the $n$-point correlation functions of the density of states $\rho(E)$. These are typically expressed in terms of the smooth correlation functions $R_n(E_1, \dots, E_n)$, which encode non-trivial statistical correlations among the eigenvalues. However, to account for coincident eigenvalues where two or more energy levels are equal, one must also include contact terms (self-correlation), which involve delta functions reflecting the singular nature of the spectrum at such points. For instance, the spectral two-point function takes the form
L001015	\begin{equation}
L001016	\begin{split}
L001017	   \overline{\langle \rho(E_i)\rho(E_j)\rangle}  &=   R_2 (K_i, K_j)  + \delta(E_i -E_j) \rho(E_i) \,.
L001018	\end{split}
L001019	\end{equation}
L001020	Alternatively, motivated by gravitational interpretations, we can write
L001021	\begin{equation}\label{eq:rho1rho2}
L001022	     \overline{\langle \rho(E_i)\rho(E_j)\rangle} = \rho(E_i)\rho(E_j)  -    \langle \rho(E_i)\rho(E_j)\rangle_c \,,  \quad  \text{with}\quad  \langle \rho(E_i)\rho(E_j)\rangle_c = \rho(E_i) \delta(E_i -E_j) - \left( K(E_i,E_j) \right)^2\,,
L001023	\end{equation}
L001024	where the connected part corresponds to contributions from spacetime wormholes, \ie quantum corrections. In the same spirit, three-point spectral correlation function $\overline{\langle\rho(E_i)\rho(E_j)\rho(E_j)\rangle}$ is
L001025	\begin{equation}\label{eq:rho3}
L001026	\begin{split}
L001027	    \overline{ \langle \rho(E_i)\rho(E_j)\rho(E_k)\rangle }&=R_3(E_i,E_j,E_k)+\delta(E_j-E_i)\delta(E_k-E_i)R_1(E_i)\\
