L001264	\begin{cases}
L001265	\frac{1}{2} \pi  e^{-\alpha t} \left(\frac{1}{\alpha }+t\right)  \quad \longrightarrow\quad  \frac{\pi }{2 \alpha ^2}+\frac{\pi  t^2}{4} + \cdots\,,\qquad \text{Second-order pole at} \quad E_{ij} = \pm (i\alpha )   \,,\\[1em]
L001266	\frac{\sqrt{\pi } 2^{\frac{3}{2}-n} \alpha ^{\frac{5}{2}-n} t^{n-\frac{1}{2}} K_{n-\frac{1}{2}}(t \alpha )}{\Gamma (n)} \quad \longrightarrow\quad  \frac{\sqrt{\pi } \Gamma \left(n-\frac{3}{2}\right) \left(\frac{2 (3-2 n)^2}{\alpha ^2}+(5-2 n) t^2\right)}{4 \Gamma (n)} + \cdots\,, \text{nth-order pole}  \,,
L001267	\end{cases}
L001268	\end{equation}
L001269	In summary, we conclude that the necessary and sufficient condition for long-time linear growth of holographic complexity is the presence of a specific first-order pole in the matrix element of the generating function, \ie
L001270	\begin{tcolorbox}[colbacktitle=CornflowerBlue!10!lightgray!60!,coltitle=black,enhanced, attach boxed title to top center={yshift=-4mm},boxed title style={colframe=black},fonttitle=\bfseries, title={Classical linear growth and Pole Structure}]
L001271	\begin{equation}\label{eq:linearpole}
L001272	\langle E_i | \widehat{e^{-\alpha \mC }}  | E_j \rangle \sim \frac{\tilde{\alpha}}{(\tilde{\alpha} + i E_{ij} )(\tilde{\alpha} - i E_{ij})} + \mathcal{O}(\alpha^2)  \,.
L001273	\end{equation}
L001274	\end{tcolorbox}
L001275	
L001276	
L001277	
L001278	
L001279	A careful reader may notice that we have thus ignored the case of four poles located at
L001280	\begin{equation}
L001281	E_{ij} = \pm ( - i\alpha \pm \delta (\alpha) )  \,, \qquad \text{with} \qquad \lim_{\alpha \to 0}\delta (\alpha) \sim \alpha^n  \to 0\,.
L001282	\end{equation}
L001283	This configuration also leads to linear growth, since
L001284	\begin{equation}
L001285	G_{\rm classical}(\alpha, t)  \approx  e^{- \talpha t}\cos ( \delta(\alpha) t)   \qquad\to\qquad  \langle \hat{C} \rangle|_{\rm classical}  \sim  M t \left(  \cos ( \delta(\alpha) t) +  t \delta'(\alpha) \sin ( \delta(\alpha) t) \right)  \sim M t \,.
L001286	\end{equation}
L001287	However, this form is equivalent to Eq.~\eqref{eq:linearpole} up to subleading corrections. Indeed, summing such four poles gives
L001288	\begin{equation}
L001289	\frac{1 }{2}  \left(\frac{\talpha}{\talpha ^2+(\delta +E_{ij})^2}+\frac{\talpha}{\talpha ^2+(E_{ij}-\delta )^2}\right) \approx \frac{\talpha}{\alpha^2+(E_{ij})^2} -\frac{\talpha \left(\talpha ^2-3 (E_{ij})^2\right)}{\left(\talpha ^2+(E_{ij})^2\right)^3} \delta ^2 +  \mathcal{O}(\delta^3) \,,
L001290	\end{equation}
L001291	which is equivalent to Eq.~\eqref{eq:linearpole} up to subleading corrections.
