L001297	\subsection{C.2 Late-time plateau and level repulsion}
L001298	\begin{figure}[h]
L001299		\centering	\includegraphics[width=3in]{figures/Universality.pdf}
L001300		\caption{The universal time evolution of holographic and quantum complexity measures in chaotic systems. The linear growth and late-time plateau are governed by the particular pole structure and level repulsion.}\label{fig:universality}
L001301	\end{figure}
L001302	
L001303	To incorporate quantum corrections at finite $S_0$, we evaluate the generating function \eqref{eq:spectraltwopoint02} using the averaged spectral correlation function and the particular pole structure \eqref{eq:linearpole} established by the constraint from the linear growth of holographic complexity. Without loss of generality, we decompose the spectral correlation function into a contact term and a joint eigenvalue distribution:
L001304	\begin{equation}
L001305	\begin{split}
L001306	    \overline{ \langle \rho(E_i)\rho(E_j)\rangle }&=  R_2(E_i, E_j) +  \delta(E_i-E_j) \rho(E_i)  \,.\\
L001307	\end{split}
L001308	\end{equation}
L001309	In terms of a generic kernel $K(E_i,E_j)$, the joint eigenvalue distribution $R_2(E_i,E_j)$ can be further expressed as
L001310	\begin{equation}
L001311	 R_2 (E_{ij}, \bar{E})  =  K\left(E_i, E_i\right) K\left(E_j, E_j\right) - K\left(E_i, E_j\right)K\left(E_j, E_i\right) = \rho_i \rho_j - (K_{ij})^2 \,.
L001312	\end{equation}
L001313	The details of the transition from linear growth to the late-time plateau depend on the precise form of the kernel $K(E_i,E_j)$, as distinct kernels can imply different choices of closed integration contours (see the sine kernel example in Fig.~\ref{fig:contour}). However, we will focus on the late-time regime and show that the late-time plateau is universal in quantum chaotic systems. It is a direct consequence of level repulsion.
L001314	
L001315	The key is that the appropriate closed integration contour remains identical to that of the classical regime (the lower half-plane) after a sufficiently late time $t$, since only this choice ensures exponential decay of the time evolution factor $e^{-i E_{ij}t}$. Applying the residue theorem to the universal pole structure from Eq.~\eqref{eq:linearpole}, the late-time generating function is dominated by the residue, \ie
L001316	\begin{equation}
L001317	\text{late times:} \qquad G_{\rm classical}(\alpha, t)  + G_{\rm quantum}(\alpha, t)  \sim  \text{Con}+  e^{-\talpha t}  \times \left(  R_2 (E_{ij}, \bar{E})\right)\big|_{E_{ij} = - i \talpha} \,.
L001318	\end{equation}
L001319	Consequently, it generates the late-time evolution of complexity measures:
L001320	\begin{equation}
L001321	\langle \hat{C} \rangle  = \langle \hat{C} \rangle|_{\rm classical} +  \langle \hat{C} \rangle|_{\rm quantum}  \approx  M t \times  \left(  R_2 (E_{ij}, \bar{E})\right)\big|_{E_{ij} =- i \alpha = 0} \,.
L001322	\end{equation}
L001323	Importantly, the particular pole structure at $E_{ij}=-i\tilde{\alpha}$ guarantees the equivalence of two limits:
L001324	\begin{equation}
L001325	\boxed{ \lim_{\alpha \to 0} \overset{E_{ij} = -i\tilde{\alpha}}{=} \lim_{E_{ij} \to 0} \,. }
L001326	\end{equation}
L001327	Thus, the existence of a late-time plateau is equivalent to
L001328	\begin{equation}
L001329	\lim_{E_{ij} \to 0 }  R_2 (E_{i}, E_j) =R_2 (E_{i}, E_i) =0 \,.
L001330	\end{equation}
L001331	Regardless of the specific details of quantum systems, this condition is precisely a manifestation of spectral level repulsion: the probability of finding two eigenvalues arbitrarily close to each other is strongly suppressed. In summary, we conclude that the necessary and sufficient condition for the saturation of holographic complexity after the linear growth is precisely the spectral level repulsion, \viz
L001332	\begin{tcolorbox}[colbacktitle=CornflowerBlue!10!lightgray!60!,coltitle=black,enhanced, attach boxed title to top center={yshift=-4mm},boxed title style={colframe=black},fonttitle=\bfseries, title={Late-time plateau and Level repulsion}]
L001333	\begin{equation}
L001334	   R_2 (E_i, E_i) =\lim_{E_{ij} \to 0}  \left( \rho(E_i)\rho(E_j)
L001335	     - K(E_i, E_j) \right) =  \lim_{E_{ij} \to 0} \left(  0 +   (E_{ij})^\beta \right)=0   \,.
L001336	\end{equation}
L001337	\end{tcolorbox}
L001338	Here, we expanded the joint eigenvalue distribution using the Christoffel–Darboux (CD) kernel. The parameter $\beta$ is the Dyson index that characterizes the universality class of random matrices ($\beta=1,2,4$ for GOE, GUE, and GSE, respectively). All conclusions in this section straightforwardly extend to codimension-zero complexity, where three-point spectral correlation functions are involved:
L001339	\begin{equation}
L001340	\boxed{ \overline{\left\langle\rho_i \rho_j \rho_k \right\rangle }  = R_3(i,j,k)+\delta_{i,j} R_2(k,i)+\delta_{j,k} R_2(i,j)+\delta_{k,i} R_2(j,k)+\delta_{i,j} \delta_{j,k} \rho_i \,.   }
L001341	\end{equation}
L001342	In particular, the late-time plateau remains governed by level repulsion, as it implies
L001343	\begin{equation}
L001344	R_3(E_j,E_i,E_i)=0 = R_2 (E_i,E_i) \,.
L001345	\end{equation}
L001346	Remarkably, level repulsion is widely recognized as a hallmark of quantum chaos. This analysis thus demonstrates that the classical linear growth of holographic complexity at late times is inevitably offset by quantum corrections arising from the chaotic nature of holographic systems, as summarized in Figure \ref{fig:universality}. Translating this result into the context of AdS black hole geometries, we find that quantum chaos ensures the saturation of the size of black hole interiors, thereby establishing a profound connection between gravitational dynamics and quantum chaotic statistics. Finally, we emphasize that level repulsion, as a sufficient condition for the emergence of the late-time plateau, strictly applies only at leading orders. Subleading corrections to complexity measures could still exhibit growth. For instance, complexity might experience a logarithmic increase at late times, \eg,
L001347	\begin{equation}
L001348	 \mC \sim   0 \times t^n + \text{Con} +   N \log(t) + \sum_{n \ge 1} \frac{N_n}{t^n} \,,
L001349	\end{equation}
L001350	despite the fact that its time derivative asymptotically vanishes:
L001351	\begin{equation}
L001352	\lim\limits_{t \to \infty} \frac{d \mC}{dt} =\lim\limits_{t \to \infty}  \left( 0 + 0+ \frac{N}{t} - \sum_{n \ge 1} \frac{nN_n}{t^{n+1}}  \right)   = 0   \,.
L001353	\end{equation}
